// Settle Final Payload minus the policy, which is exactly what it hands to 03. The delivery row is keyed by
// the scan the clicked card came from, so it wins; the encounter row is the fallback for a modal opened
// before scan_id was carried in private_metadata, and holds the latest scan for this person.
let raw=String(row.raw_json||'');
